local GardenFurrowMaker = {}
local PRODUCTS = {
    iron_gardenfurrow = { name = "Železni brazdar za gredice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni brazdar za gredice za vrtnarje." },
    bronze_gardenfurrow = { name = "Bronast brazdar za gredice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast brazdar za gredice za vrtnarje." },
    silver_gardenfurrow = { name = "Srebrn brazdar za gredice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn brazdar za gredice za vrtnarje." },
    gilded_gardenfurrow = { name = "Pozlačen brazdar za gredice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen brazdar za gredice za vrtnarje." },
    jewel_set_gardenfurrow = { name = "Draguljast brazdar za gredice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast brazdar za gredice za vrtnarje." },
    royal_sovereign_gardenfurrow = { name = "Kraljevski suveren brazdar za gredice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren brazdar za gredice z biseri za krono." },
}
local BUILDINGS = {
    gardenfurrow_workshop = { name = "Gardenfurrow delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenfurrow_house = { name = "Gardenfurrow hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenfurrow_atelier = { name = "Mojstrski gardenfurrow atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenfurrow_palace = { name = "Suverena gardenfurrow palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenFurrowMaker.ironStock=16; GardenFurrowMaker.bronzeStock=12; GardenFurrowMaker.woodStock=12; GardenFurrowMaker.leatherStock=8; GardenFurrowMaker.silverStock=8; GardenFurrowMaker.goldStock=6; GardenFurrowMaker.jewelStock=4; GardenFurrowMaker.pearlStock=4
GardenFurrowMaker.productStock = {}; GardenFurrowMaker.buildings = {}; GardenFurrowMaker.maker = nil; GardenFurrowMaker.activeMaking = {}; GardenFurrowMaker.totalProducts = 0; GardenFurrowMaker.dayTimer = 0
function GardenFurrowMaker.init() GardenFurrowMaker.ironStock=16; GardenFurrowMaker.bronzeStock=12; GardenFurrowMaker.woodStock=12; GardenFurrowMaker.leatherStock=8; GardenFurrowMaker.silverStock=8; GardenFurrowMaker.goldStock=6; GardenFurrowMaker.jewelStock=4; GardenFurrowMaker.pearlStock=4; GardenFurrowMaker.productStock={}; GardenFurrowMaker.buildings={}; GardenFurrowMaker.maker=nil; GardenFurrowMaker.activeMaking={}; GardenFurrowMaker.totalProducts=0; GardenFurrowMaker.dayTimer=0; print("[GardenFurrowMaker] Royal Garden Furrow Maker System initialized (6 products, 4 buildings)") end
function GardenFurrowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenFurrowMaker.maker={name=n or ("Brazdar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brazdar najet: %s (spretnost: %d)",GardenFurrowMaker.maker.name,s),"success") end; return true end
function GardenFurrowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenFurrowMaker.build(id) local ok,e=GardenFurrowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenFurrowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenFurrowMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenFurrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenFurrowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenFurrowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenFurrowMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenFurrowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenFurrowMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenFurrowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenFurrowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenFurrowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenFurrowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenFurrowMaker.buildings==0 then return false,"Potrebna brazdarska delavnica" end; if not GardenFurrowMaker.maker then return false,"Potreben brazdar" end; return true end
function GardenFurrowMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenFurrowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenFurrowMaker.ironStock=GardenFurrowMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenFurrowMaker.bronzeStock=GardenFurrowMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenFurrowMaker.woodStock=GardenFurrowMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenFurrowMaker.leatherStock=GardenFurrowMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenFurrowMaker.silverStock=GardenFurrowMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenFurrowMaker.goldStock=GardenFurrowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenFurrowMaker.jewelStock=GardenFurrowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenFurrowMaker.pearlStock=GardenFurrowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenFurrowMaker.maker then t=math.max(1,t-math.floor(GardenFurrowMaker.maker.skill/13)) end; table.insert(GardenFurrowMaker.activeMaking,{id="gardenfurrow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenFurrowMaker.completeMaking(m) local q=1.0+(GardenFurrowMaker.getQualityBonus()/100); if GardenFurrowMaker.maker then q=q+(GardenFurrowMaker.maker.skill/140) end; q=math.min(2.5,q); GardenFurrowMaker.productStock[m.productType]=(GardenFurrowMaker.productStock[m.productType] or 0)+m.quantity; GardenFurrowMaker.totalProducts=GardenFurrowMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenFurrowMaker.maker then GardenFurrowMaker.maker.itemsMade=GardenFurrowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenFurrowMaker.maker.skill=math.min(100,GardenFurrowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brazda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenfurrow.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenFurrowMaker.update(dt) if not _G.state then return end; GardenFurrowMaker.dayTimer=GardenFurrowMaker.dayTimer+dt; if GardenFurrowMaker.dayTimer>=30 then GardenFurrowMaker.dayTimer=0; for i=#GardenFurrowMaker.activeMaking,1,-1 do local m=GardenFurrowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenFurrowMaker.completeMaking(m); table.remove(GardenFurrowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenFurrowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenFurrowMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenFurrowMaker.getStats() return {ironStock=GardenFurrowMaker.ironStock,bronzeStock=GardenFurrowMaker.bronzeStock,woodStock=GardenFurrowMaker.woodStock,leatherStock=GardenFurrowMaker.leatherStock,silverStock=GardenFurrowMaker.silverStock,goldStock=GardenFurrowMaker.goldStock,jewelStock=GardenFurrowMaker.jewelStock,pearlStock=GardenFurrowMaker.pearlStock,productStock=GardenFurrowMaker.productStock,numBuildings=#GardenFurrowMaker.buildings,hasMaker=GardenFurrowMaker.maker~=nil,makerName=GardenFurrowMaker.maker and GardenFurrowMaker.maker.name or "—",makerSkill=GardenFurrowMaker.maker and GardenFurrowMaker.maker.skill or 0,activeMaking=#GardenFurrowMaker.activeMaking,totalProducts=GardenFurrowMaker.totalProducts} end
return GardenFurrowMaker
